import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import styles from "../css/Home.module.css"
import { GoogleLogin } from '@react-oauth/google';

REACT_APP_GOOGLE_CLIENT_ID="19920393137-onp2l76g18siigg7v6djsstqgohm7ukq.apps.googleusercontent.com"

function Home() {
  const navigate = useNavigate();  // useNavigate 사용
  const [currentDateTime, setCurrentDateTime] = useState('');

  // 현재 날짜와 시간을 반환하는 함수 (24시간 기준, 분까지만 표시)
  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',  // 요일을 포함하도록 설정
    }); // 예: "2025년 1월 11일 금요일"
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false, // 24시간 형식
    }); // 예: "15:05"

    return `${date} ${time}`; // 예: "2025년 1월 11일 금요일 15:05"
  };

  // 컴포넌트가 마운트될 때마다 시간을 갱신하도록 설정
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000); // 1초마다 시간을 갱신

    // 처음에 한 번 바로 시간을 갱신
    setCurrentDateTime(getCurrentDateTime());

    // 컴포넌트가 언마운트될 때 interval을 클리어
    return () => clearInterval(interval);
  }, []);

  // Google 로그인 후 ID 토큰을 받아 서버로 전달하는 함수
  const handleLoginSuccess = (response) => {
    const id_token = response.credential; // Google 로그인 성공 후 받아오는 ID 토큰

    // ID 토큰을 서버로 전송 (백엔드에서 처리)
    fetch('/callback', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        id_token: id_token,
      }),
    })
      .then(response => response.json())
      .then(data => {
        // 로그인 성공 후 처리 (예: 사용자 정보를 세션에 저장 등)
        console.log('User Info:', data);
        navigate("/profile"); // 프로필 페이지로 리디렉션
      })
      .catch(error => console.error('Error:', error));
  };

  // Google 로그인 실패 처리 함수
  const handleLoginFailure = (error) => {
    console.log('Login Failed:', error);
  };

  return (
    <div id="home-component" className={styles.homeContainer}>
      {/* 오늘 날짜와 시간 표시 */}
      <div id="home-datetime" className={styles.homeDatetime}>
        <strong>{currentDateTime}</strong>
      </div>
      <h1 id="home-title" className={styles.homeTitle}>Welcome to Chatbot</h1>
      <button id="home-start-btn" className={styles.homeButton} onClick={() => navigate("/settings")}>시작하기</button>

      {/* Google 로그인 버튼 */}
      <div className="google-login-container">
        <GoogleLogin
          onSuccess={handleLoginSuccess}
          onError={handleLoginFailure}
          clientId={process.env.REACT_APP_GOOGLE_CLIENT_ID}
        />
      </div>
    </div>
  );
}

export default Home;
